def page(title: str, body: str, css: str = CSS) -> str:
    return f"<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{html.escape(title)}</title><script id='MathJax-script' async src='https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js'></script><style>{css}</style></head><body>{body}</body></html>"

def header(title: str, subtitle: str) -> str:
    return f"<header><div><h1>{html.escape(title)}</h1><p>{html.escape(subtitle)}</p></div></header>"

def bullets(items: list[str]) -> str:
    return "<ul>" + "".join(f"<li>{html.escape(item)}</li>" for item in items) + "</ul>"

def fmt(value: float, digits: int = 5) -> str:
    return f"{value:.{digits}g}"

def calculation(i: int) -> tuple[str, str]:
    if i == 1:
        value = 5 * KEV_J / 1.380649e-23
        return f"T = {fmt(value)} K", "The ideal-gas conversion treats the quoted energy as a thermal scale, not a measured temperature for every particle."
    if i == 2:
        mdot = 1e-9 * MSUN / (365.25 * 86400)
        luminosity = G * (10 * MSUN) * mdot / (30e3)
        return f"Lacc = {fmt(luminosity)} W and Lacc/(mdot c^2) = {fmt(luminosity/(mdot*(C*1000)**2))}", "The radius is an illustrative inner-disk scale; spin and relativistic efficiency are omitted."
    if i == 3:
        gravity = G * MSUN / (0.01 * RSUN) ** 2
        return f"g = {fmt(gravity)} m/s^2 = {fmt(gravity/9.80665)} Earth g", "The comparison is greater than Earth gravity; it is not a claim that a white dwarf has a solid surface."
    if i == 4:
        radius_pc = 5000 * 1000 * 365.25 * 86400 / (3.085677581e13)
        return f"R = {fmt(radius_pc)} pc", "Constant velocity is a deliberately limited first model; Sedov evolution decelerates the shock."
    if i == 5:
        age = 0.033 / (2 * 4.2e-13) / (365.25 * 86400)
        speed = 2 * math.pi * 10000 / 0.033
        return f"tau_c = {fmt(age)} yr; v_eq = {fmt(speed)} m/s", "The equatorial speed remains well below c, while the timing age is model-dependent."
    if i == 6:
        compact = 2 * G * 1.4 * MSUN / (12000 * (299792458.0 ** 2))
        z = (1 - compact) ** -0.5 - 1
        return f"2GM/(Rc^2) = {fmt(compact)} and z = {fmt(z)}", "The spherical, static metric is an approximation; rotation and atmosphere modeling affect inferred radius."
    if i == 7:
        rs_km = 2 * G * 21 * MSUN / (299792458.0 ** 2) / 1000
        return f"r_s = {fmt(rs_km)} km", "A horizon-scale length is not a direct image of the horizon; binary dynamics and disk emission are separate evidence streams."
    if i == 8:
        au = (C * 86400 * 10 / 1.5) / 1.495978707e8
        return f"R < {fmt(au)} AU", "The bound assumes the observed variability is intrinsic and that the Doppler factor is known."
    if i == 9:
        kt = 3 * 0.61 * 1.67262192369e-27 * (5e6 ** 2) / 16 / KEV_J
        return f"kT2 = {fmt(kt)} keV", "The Rankine-Hugoniot estimate assumes a strong, non-radiative shock and rapid ionization."
    if i == 10:
        rl = (1e15 * 1.602176634e-19) / (299792458.0 * 1.602176634e-19 * 3e-10)
        return f"r_L approximately {fmt(rl/3.085677581e16)} pc", "The estimate uses pc approximately equal to E/c and shows why Galactic magnetic fields erase arrival directions."
    if i == 11:
        return "The common energy interval is 1.0-10.0 keV.", "Energy-band overlap does not mean identical effective area, response, background, or timing performance."
    if i == 12:
        return f"S/N = {fmt(40*math.sqrt(25)/math.sqrt(40+160))}", "The Poisson expression assumes independent counts and a stable background estimate."
    if i == 13:
        return "With alpha=1 and F0=100 at t0=1 hour, F=25 occurs at t=4 hours.", "A power law is a model comparison tool, not a physical explanation by itself."
    score = 0.35 * 4 / 5 + 0.25 * 3 / 5 + 0.20 * 5 / 5 + 0.20 * 2 / 5
    return f"Weighted project score = {fmt(score, 4)} of 1.0", "The score is a transparent planning aid; scientific value cannot be reduced to one scalar."

