        f'<ellipse cx="210" cy="150" rx="145" ry="72" fill="none" stroke="{n}" stroke-width="4"/><ellipse cx="210" cy="150" rx="82" ry="31" fill="none" stroke="{t}" stroke-width="9"/><circle cx="210" cy="150" r="19" fill="{r}"/><path d="M70 125L345 175" stroke="{g}" stroke-width="4" stroke-dasharray="9 6"/><text x="120" y="285">energy release follows binding radius</text>',
