        f'<circle cx="215" cy="150" r="115" fill="#e8f1f2" stroke="{n}" stroke-width="4"/><path d="M215 35C120 85 120 215 215 265M215 35C310 85 310 215 215 265" fill="none" stroke="{t}" stroke-width="5"/><path d="M100 150H330" stroke="{g}" stroke-width="5" stroke-dasharray="8 6"/><text x="125" y="285">charged-particle deflection</text>',
        f'<rect x="75" y="75" width="65" height="150" fill="{t}"/><rect x="180" y="105" width="65" height="120" fill="{g}"/><rect x="285" y="140" width="65" height="85" fill="{r}"/><path d="M55 245H380" stroke="{n}" stroke-width="3"/><text x="88" y="55">effective area</text><text x="175" y="285">response channels</text>',
