def write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")

def build() -> None:
    for folder in (LECTURES, LABS, PSETS, DATA):
        folder.mkdir(parents=True, exist_ok=True)
    for i, item in enumerate(LECTURE_DATA, 1):
        slides, notes = lecture_pages(i, item)
        write(LECTURES / f"lecture-{i:02d}-slides.html", slides)
        write(LECTURES / f"lecture-{i:02d}-notes.html", notes)
    datasets = {
        "xray_spectrum.csv": (["energy_kev", "counts", "background"], [[1, 420, 30], [2, 380, 28], [5, 210, 22], [8, 95, 18], [10, 50, 17]]),
        "binary_accretion.csv": (["object", "mass_msun", "radius_km", "mdot_msun_yr"], [["white dwarf", 1.0, 6000, 1e-9], ["neutron star", 1.4, 12, 1e-9], ["black hole", 10.0, 30, 1e-9]]),
        "snr_shock.csv": (["target", "shock_km_s", "radius_arcmin", "distance_kpc"], [["teaching SNR", 5000, 2.0, 2.5], ["fast comparison", 10000, 1.0, 5.0]]),
        "pulsar_timing.csv": (["target", "period_s", "perioddot"], [["Crab-like", 0.033, 4.2e-13], ["slow pulsar", 0.5, 1e-15]]),
        "neutron_star_models.csv": (["model", "mass_msun", "radius_km"], [["A", 1.4, 10.5], ["B", 1.4, 12.0], ["C", 1.4, 13.5]]),
        "mission_specs.csv": (["mission", "band", "primary_strength"], [["Chandra", "X-ray", "imaging/spectroscopy"], ["NICER", "0.2-12 keV", "timing/spectroscopy"], ["Swift", "15-150 keV plus 0.3-10 keV", "rapid burst localization/follow-up"], ["Fermi", "gamma-ray", "wide-field survey"], ["IceCube", "neutrino", "particle direction/energy"]]),
        "transient_dossier.csv": (["candidate", "science", "feasibility", "data_access", "systematics"], [["GRB", 4, 4, 5, 3], ["TDE", 5, 2, 4, 4], ["magnetar flare", 4, 3, 3, 2]]),
    }
    for name, (head, rows) in datasets.items():
        with (DATA / name).open("w", newline="", encoding="utf-8") as handle:
            writer = csv.writer(handle)
            writer.writerow(head)
            writer.writerows(rows)
    for i, spec in enumerate(LABS_DATA, 1):
        write(LABS / f"lab-{i:02d}.html", lab_html(i, spec))
        student, solution, assessment = pset(i, spec)
        write(PSETS / f"problem-set-{i:02d}.html", student)
        write(PSETS / f"problem-set-{i:02d}-solutions.html", solution)
        write(PSETS / f"problem-set-{i:02d}-assessment.md", assessment)
    write(DATA / "README.md", "# ASTR 470 Data\n\nThese compact CSVs are level-3 instructor-provided teaching records generated for reproducible exercises. They are not archive downloads or new observations. Real mission facts are separated in `reference-log.md`; level-2 object parameters require human spot-check before live use.\n")
    write(ROOT / "src" / "README.md", "# ASTR 470 Source\n\n`generate_astr470_package.py` owns shared constants, calculations, distinct SVG builders, and generated artifacts. Re-run it after changing data, then independently recompute at least one result per lecture, lab, and problem set.\n")
    write(ROOT / "README.md", "# ASTR 470 High-Energy Astrophysics\n\nComplete Year 4 elective package on compact objects, accretion, remnants, pulsars, black holes, AGN, cosmic rays, high-energy instrumentation, and transients.\n")
    write(ROOT / "syllabus.html", syllabus())
    write(ROOT / "schedule.html", schedule())
    write(ROOT / "reference-log.md", reference_log())
    write(ROOT / "index.html", index_html())
    manifest = {"course": {"courseNumber": "ASTR 470", "courseCode": "ASTR470", "title": "High-Energy Astrophysics", "credits": 3, "term": "Year 4 elective", "yearInCurriculum": 4, "prerequisites": "ASTR330; PHYS341 recommended", "description": "Compact objects, accretion disks, supernova remnants, pulsars, black holes, active galactic nuclei, cosmic rays, X-ray/gamma-ray instrumentation, and transients."}, "status": {"stage": "approved for review release", "reviewStatus": "Approved for review release; not yet approved for instructional use", "lastUpdated": "2026-09-25"}, "counts": {"slides": 14, "notes": 14, "labs": 7, "problemSets": 7, "solutionKeys": 7, "assessmentInstructions": 7}, "cadence": {"lectures": 14, "labs": 7, "problemSets": 7, "rationale": "Matched two-lecture units: each lab and problem set follows the second lecture so source physics and instrument/statistical context are both available."}, "dataProvenance": {"generator": "materials/ASTR470/src/generate_astr470_package.py", "levels": {"level1": "Official mission documentation fetched this session and listed in reference-log.md.", "level2": "Standard published object parameters not re-verified this session; human spot-check required.", "level3": "Compact CSVs, computed teaching records, scores, and SVGs are instructor-provided."}}}
    write(ROOT / "course-manifest.json", json.dumps(manifest, indent=2) + "\n")

if __name__ == "__main__":
    build()